mapper.select:
SELECT id AS sequence,tenant_id AS tenantId,parent_run_id AS parentRunId,task_id AS taskId,
       child_agent_id AS childAgentId,result_summary AS resultSummary,task_status AS taskStatus
FROM agent_parent_inbox WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId}
  AND id > #{cursor} AND consumed_at IS NULL AND deleted=0 ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE agent_parent_resume_request SET lease_expires_at=#{leaseExpiresAt}
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND status='RUNNING'
  AND lease_owner=#{workerId} AND fencing_token=#{fencingToken}
  AND lease_expires_at >= #{now} AND deleted=0

UPDATE agent_parent_inbox SET consumed_at=#{deliveredAt}
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND consumed_at IS NULL AND deleted=0
  AND task_id IN #{taskId}

UPDATE agent_parent_resume_request
SET status=IF(requested_version=#{requestedVersion} AND NOT EXISTS (
      SELECT 1 FROM agent_parent_inbox pending
      WHERE pending.tenant_id=#{tenantId} AND pending.parent_run_id=#{parentRunId}
        AND pending.id > #{cursor} AND pending.consumed_at IS NULL AND pending.deleted=0
    ),'COMPLETED','PENDING'),
    processed_version=#{requestedVersion},inbox_cursor=GREATEST(inbox_cursor,#{cursor}),
    next_attempt_at=#{deliveredAt},lease_owner=NULL,lease_expires_at=NULL,last_error=NULL,updated_at=#{deliveredAt}
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND status='RUNNING'
  AND lease_owner=#{workerId} AND fencing_token=#{fencingToken} AND deleted=0

UPDATE agent_parent_resume_request SET recovery_notified_at=#{now}
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND status=#{status}
  AND fencing_token=#{fencingToken} AND deleted=0
  AND (recovery_notified_at IS NULL OR recovery_notified_at < #{staleBefore})
